use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut pendingquote = false
        for c in line.chars() {
            if inq {
                if pendingquote {
                    if c == '"' {
                        cur = cur + "\""
                        pendingquote = false
                    } else {
                        inq = false
                        pendingquote = false
                        if c == ',' {
                            fields.push(cur)
                            cur = ""
                        } else {
                            cur = cur + c.to_string()
                        }
                    }
                } else if c == '"' {
                    pendingquote = true
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else if c == '"' {
                inq = true
            } else {
                cur = cur + c.to_string()
            }
        }
        fields.push(cur)
        let mut out = ""
        let mut first = true
        for f in fields {
            if !first {
                out = out + "|"
            }
            first = false
            out = out + "[" + f + "]"
        }
        let n: int = fields.len() as int
        println("${n}: ${out}")
    }
}

